/** Stateless query/enrichment engine for future Doctor Discovery. */
final class DDD_Future_Query {
	const MAX_RESULTS=60; const CONTRACT_VERSION='1.0';
	public static function args(){ $o=array();foreach(array('q','country','city','specialty','language','qualification','currency','fee_min','fee_max','serves_country','books','teaching','research','lat','lng','timezone','weights','cursor') as$k)$o[$k]=array('sanitize_callback'=>'sanitize_text_field');foreach(array('min_experience','availability_days','radius_km','limit') as$k)$o[$k]=array('sanitize_callback'=>'absint');foreach(array('mode','practice_type','communication_accessibility','clinic_accessibility') as$k)$o[$k]=array('sanitize_callback'=>'sanitize_key');$o['accepting']=array('sanitize_callback'=>'rest_sanitize_boolean');$o['limit']['default']=24;return$o;}
	public static function sanitize($r){$mode=sanitize_key((string)($r['mode']??''));if(!in_array($mode,array('','online','in-person','video','phone','chat','home-visit'),true))$mode='';return array('q'=>sanitize_text_field((string)($r['q']??'')),'country'=>sanitize_text_field((string)($r['country']??'')),'city'=>sanitize_text_field((string)($r['city']??'')),'specialty'=>sanitize_text_field((string)($r['specialty']??'')),'language'=>sanitize_text_field((string)($r['language']??'')),'qualification'=>sanitize_text_field((string)($r['qualification']??'')),'min_experience'=>min(100,absint($r['min_experience']??0)),'mode'=>$mode,'accepting'=>rest_sanitize_boolean($r['accepting']??false),'currency'=>strtoupper(substr(sanitize_text_field((string)($r['currency']??'')),0,3)),'fee_min'=>DDD_Helpers::decimal_or_null($r['fee_min']??null),'fee_max'=>DDD_Helpers::decimal_or_null($r['fee_max']??null),'serves_country'=>sanitize_text_field((string)($r['serves_country']??'')),'availability_days'=>min(90,absint($r['availability_days']??0)),'books'=>sanitize_text_field((string)($r['books']??'')),'teaching'=>sanitize_text_field((string)($r['teaching']??'')),'research'=>sanitize_text_field((string)($r['research']??'')),'practice_type'=>sanitize_key((string)($r['practice_type']??'')),'communication_accessibility'=>sanitize_key((string)($r['communication_accessibility']??'')),'clinic_accessibility'=>sanitize_key((string)($r['clinic_accessibility']??'')),'lat'=>self::coord($r['lat']??null,-90,90),'lng'=>self::coord($r['lng']??null,-180,180),'radius_km'=>min(250,max(1,absint($r['radius_km']??25))),'timezone'=>self::tz($r['timezone']??''),'weights'=>sanitize_text_field((string)($r['weights']??'')),'cursor'=>sanitize_text_field((string)($r['cursor']??'')),'limit'=>min(self::MAX_RESULTS,max(1,absint($r['limit']??24))));}
	private static function coord($v,$a,$b){if($v===null||$v===''||!is_numeric($v))return null;$v=(float)$v;return$v>=$a&&$v<=$b?$v:null;} private static function tz($v){$v=sanitize_text_field((string)$v);return in_array($v,timezone_identifiers_list(),true)?$v:'UTC';}
	public static function repository($p){return array_intersect_key($p,array_flip(array('q','country','city','specialty','language','qualification','min_experience','mode','accepting','currency','fee_min','fee_max','cursor','limit')));}
	public static function interpret($query){$q=mb_strtolower(sanitize_text_field($query));foreach(array('chest pain','cannot breathe','difficulty breathing','unconscious','severe bleeding','stroke','suicide','خودکشی','سانس نہیں','سانس لینے میں شدید','سینے میں شدید درد','بے ہوش','شدید خون')as$n)if(mb_strpos($q,$n)!==false)return array('safety_diversion'=>array('code'=>'possible_emergency','message'=>__('This directory is not an emergency-triage service. Seek appropriate local emergency or urgent medical care now.',DDD_TEXT_DOMAIN),'directory_suppressed'=>true));$o=array('q'=>trim($query),'original_query'=>trim($query),'expanded_terms'=>array());$dict=array('online'=>array('online','آن لائن','video','ویڈیو'),'in-person'=>array('in person','in-person','clinic','کلینک','روبرو'),'urdu'=>array('urdu','اردو'),'english'=>array('english','انگلش','انگریزی'),'arabic'=>array('arabic','عربی'));foreach($dict as$c=>$ws)foreach($ws as$w)if(mb_strpos($q,$w)!==false){if(in_array($c,array('online','in-person'),true))$o['mode']=$c;else$o['language']=ucfirst($c);$o['expanded_terms'][]=$c;break;}$res=$q;foreach(array('doctor','doctors','homeopath','homeopathic','speaking','available','availability','online','video','in person','in-person','clinic','near','me','who','this','week','today','tomorrow','in','for','آن لائن','ویڈیو','کلینک','روبرو','ڈاکٹر','طبیب','بولنے والا','بولنے والی','دستیاب','قریب','اردو','انگلش','انگریزی','عربی')as$w)$res=str_replace(mb_strtolower($w),' ',$res);$o['residual_q']=sanitize_text_field((string)preg_replace('/\s+/u',' ',trim($res)));$custom=apply_filters('ddd_file07_semantic_dictionary_v1',array(),$q);if(is_array($custom)){foreach(array('country','city','specialty','language','mode')as$k)if(!empty($custom[$k]))$o[$k]=sanitize_text_field((string)$custom[$k]);$o['expanded_terms']=array_values(array_unique(array_merge($o['expanded_terms'],array_map('sanitize_text_field',(array)($custom['expanded_terms']??array())))));}return$o;}
	public static function merge($p,$i){foreach(array('country','city','specialty','language','mode')as$k)if(empty($p[$k])&&!empty($i[$k]))$p[$k]=$i[$k];if(!empty($i['expanded_terms'])&&array_key_exists('residual_q',$i))$p['q']=$i['residual_q'];return$p;}
	public static function enrich($d,$p){$id=sanitize_text_field((string)($d['public_id']??''));$ctx=array('consumer'=>'file07','purpose'=>'doctor_discovery','contract_version'=>self::CONTRACT_VERSION);$c=self::clean(apply_filters('ddd_file08_public_discovery_v1',array(),$id,$ctx));$pro=self::clean(apply_filters('ddd_file03_public_professional_discovery_v1',array(),$id,$ctx));$know=self::clean(apply_filters('ddd_public_knowledge_footprint_v1',array(),$id,$ctx));$d['discovery_extensions']=array('clinic'=>$c,'professional'=>$pro,'knowledge'=>$know);$d['freshness']=array('verification'=>sanitize_text_field((string)($d['verified_at']??'')),'profile'=>sanitize_text_field((string)($pro['updated_at']??'')),'availability'=>sanitize_text_field((string)($c['availability_updated_at']??'')));if($p['lat']!==null&&$p['lng']!==null&&isset($c['lat'],$c['lng'])&&is_numeric($c['lat'])&&is_numeric($c['lng']))$d['distance_km']=round(self::distance($p['lat'],$p['lng'],(float)$c['lat'],(float)$c['lng']),1);$d['local_availability']=self::local($c,$p['timezone']);return$d;}
	private static function clean($v){if(!is_array($v))return array();$ok=array('lat','lng','clinic_timezone','next_available_at','availability_updated_at','countries_served','books_studied','teaching_experience','research_activity','communication_accessibility','clinic_accessibility','languages_proficiency','practice_type','home_visit','knowledge_counts','updated_at','slots');$o=array();foreach($ok as$k)if(array_key_exists($k,$v)){if(is_array($v[$k])){$a=array();foreach(array_slice($v[$k],0,50,true)as$x=>$y)if(is_scalar($y))$a[is_string($x)?sanitize_key($x):$x]=sanitize_text_field((string)$y);$o[$k]=$a;}elseif(is_scalar($v[$k]))$o[$k]=sanitize_text_field((string)$v[$k]);}return$o;}
	public static function matches($d,$p){$e=(array)($d['discovery_extensions']??array());$c=(array)($e['clinic']??array());$pro=(array)($e['professional']??array());if($p['lat']!==null&&$p['lng']!==null&&(!isset($d['distance_km'])||$d['distance_km']>$p['radius_km']))return false;if($p['serves_country']&&!self::has($c['countries_served']??array(),$p['serves_country']))return false;if($p['availability_days']){$n=strtotime((string)($c['next_available_at']??''));if(!$n||$n>time()+$p['availability_days']*DAY_IN_SECONDS)return false;}if($p['books']&&!self::has($pro['books_studied']??array(),$p['books']))return false;if($p['teaching']&&mb_strpos(DDD_Helpers::normalize_token((string)($pro['teaching_experience']??'')),DDD_Helpers::normalize_token($p['teaching']))===false)return false;if($p['research']&&mb_strpos(DDD_Helpers::normalize_token((string)($pro['research_activity']??'')),DDD_Helpers::normalize_token($p['research']))===false)return false;if($p['practice_type']&&DDD_Helpers::normalize_token((string)($pro['practice_type']??''))!==DDD_Helpers::normalize_token($p['practice_type']))return false;if($p['communication_accessibility']&&!self::has($pro['communication_accessibility']??array(),$p['communication_accessibility']))return false;if($p['clinic_accessibility']&&!self::has($c['clinic_accessibility']??array(),$p['clinic_accessibility']))return false;return true;}
	public static function saved_match($d,$p){if($p['country']&&strcasecmp((string)($d['country']??''),$p['country']))return false;if($p['city']&&strcasecmp((string)($d['city']??''),$p['city']))return false;if($p['language']&&!self::has($d['languages']??array(),$p['language']))return false;if($p['mode']&&!self::has($d['consultation_modes']??array(),$p['mode']))return false;if($p['specialty']&&mb_strpos(DDD_Helpers::normalize_token((string)($d['specialty']??'')),DDD_Helpers::normalize_token($p['specialty']))===false)return false;if($p['accepting']&&empty($d['accepting_patients']))return false;return self::matches($d,$p);}
	private static function has($h,$n){$n=DDD_Helpers::normalize_token($n);foreach((array)$h as$v)if(mb_strpos(DDD_Helpers::normalize_token($v),$n)!==false)return true;return false;}
	public static function why($d,$p){$w=array();if($p['language']&&self::has($d['languages']??array(),$p['language']))$w[]=sprintf(__('Speaks %s',DDD_TEXT_DOMAIN),$p['language']);if($p['city']&&!strcasecmp((string)($d['city']??''),$p['city']))$w[]=sprintf(__('Located in %s',DDD_TEXT_DOMAIN),$p['city']);if($p['mode']&&self::has($d['consultation_modes']??array(),$p['mode']))$w[]=sprintf(__('Offers %s consultation',DDD_TEXT_DOMAIN),$p['mode']);if(isset($d['distance_km']))$w[]=sprintf(__('Approximately %s km away',DDD_TEXT_DOMAIN),number_format_i18n($d['distance_km'],1));if(!empty($d['local_availability']['next_local']))$w[]=__('Has published upcoming availability',DDD_TEXT_DOMAIN);if(!empty($d['freshness']['verification']))$w[]=__('Verification is current in the public projection',DDD_TEXT_DOMAIN);return array_slice(array_values(array_unique($w)),0,6);}
	private static function local($c,$tz){$n=(string)($c['next_available_at']??'');if(!$n)return array();try{$dt=new DateTimeImmutable($n,new DateTimeZone(self::tz($c['clinic_timezone']??'UTC')));$t=new DateTimeZone(self::tz($tz));return array('next_local'=>$dt->setTimezone($t)->format(DATE_ATOM),'timezone'=>$t->getName());}catch(Exception$e){return array();}}
	private static function distance($a,$b,$c,$d){$r=6371.0088;$p1=deg2rad($a);$p2=deg2rad($c);$dp=deg2rad($c-$a);$dl=deg2rad($d-$b);$x=sin($dp/2)**2+cos($p1)*cos($p2)*sin($dl/2)**2;return$r*2*atan2(sqrt($x),sqrt(1-$x));}
	public static function map_points($items){$o=array();foreach($items as$d){$c=(array)($d['discovery_extensions']['clinic']??array());if(isset($c['lat'],$c['lng'])&&is_numeric($c['lat'])&&is_numeric($c['lng']))$o[]=array('public_id'=>(string)$d['public_id'],'name'=>(string)$d['display_name'],'lat'=>(float)$c['lat'],'lng'=>(float)$c['lng'],'distance_km'=>$d['distance_km']??null);}return array_slice($o,0,self::MAX_RESULTS);}
	private static function weights($raw){$d=json_decode(wp_unslash((string)$raw),true);if(!is_array($d))return array();$o=array();foreach(array('distance','language','availability','fee','experience')as$k)if(isset($d[$k]))$o[$k]=min(10,max(0,(float)$d[$k]));return array_filter($o,static function($v){return$v>0;});}
	public static function personal($items,$raw,$p,&$used){$w=self::weights($raw);$used=(bool)$w;if(!$w)return$items;foreach($items as&$d){$s=0.0;if(isset($w['distance'],$d['distance_km']))$s+=$w['distance']*max(0,100-min(100,$d['distance_km']));if(isset($w['language'])&&!empty($p['language'])&&self::has($d['languages']??array(),$p['language']))$s+=$w['language']*100;if(isset($w['availability'])&&!empty($d['local_availability']['next_local'])){$h=max(0,(strtotime($d['local_availability']['next_local'])-time())/HOUR_IN_SECONDS);$s+=$w['availability']*max(0,100-min(100,$h/2));}if(isset($w['fee'])&&!empty($p['currency'])&&isset($d['fee_min'],$d['currency'])&&is_numeric($d['fee_min'])&&!strcasecmp((string)$d['currency'],$p['currency']))$s+=$w['fee']*max(0,100-min(100,(float)$d['fee_min']/100));if(isset($w['experience']))$s+=$w['experience']*min(100,(float)($d['experience_years']??0)*3);$d['personal_score']=round($s,3);$d['personal_order']=true;}unset($d);usort($items,static function($a,$b){return($b['personal_score']??0)<=>($a['personal_score']??0);});return$items;}
	public static function zero_result_recovery($p){$o=array();if($p['city'])$o[]=array('action'=>'remove_city','label'=>__('Search the whole country',DDD_TEXT_DOMAIN));if($p['country'])$o[]=array('action'=>'allow_online','label'=>__('Include online doctors who serve your country',DDD_TEXT_DOMAIN));if($p['fee_max']!==null)$o[]=array('action'=>'relax_fee','label'=>__('Increase the fee range',DDD_TEXT_DOMAIN));if($p['availability_days'])$o[]=array('action'=>'relax_availability','label'=>__('Show later availability',DDD_TEXT_DOMAIN));if($p['lat']!==null)$o[]=array('action'=>'widen_radius','label'=>__('Widen nearby radius',DDD_TEXT_DOMAIN));if($p['language'])$o[]=array('action'=>'remove_language','label'=>__('Show other languages',DDD_TEXT_DOMAIN));return array_slice($o,0,6);}
}
